ss_counter.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_counter is
  generic (WIDTH:positive range 1 to 64:=8; WRAP:natural range 0 to 1:=1);
  port (clk,rst,en,load,down:in std_logic;
    minimum,maximum,load_value:in std_logic_vector(WIDTH-1 downto 0);
    q:out std_logic_vector(WIDTH-1 downto 0);
    valid,terminal,wrapped:out std_logic);
end entity;
architecture rtl of ss_counter is
  signal value:unsigned(WIDTH-1 downto 0):=(others=>'0');
  signal wrap_event:std_logic:='0';
begin
  q <= std_logic_vector(value);
  valid <= '1' when unsigned(minimum)<=unsigned(maximum) and value>=unsigned(minimum) and value<=unsigned(maximum) else '0';
  terminal <= '1' when unsigned(minimum)<=unsigned(maximum) and
    ((down='0' and value=unsigned(maximum)) or (down='1' and value=unsigned(minimum))) else '0';
  wrapped <= wrap_event;
  process(clk)
    variable lo,hi,first:unsigned(WIDTH-1 downto 0);
  begin
    if rising_edge(clk) then
      lo:=unsigned(minimum); hi:=unsigned(maximum);
      first:=lo; if down='1' then first:=hi; end if;
      wrap_event<='0';
      if rst='1' then value<=first;
      elsif lo<=hi then
        if load='1' then
          if unsigned(load_value)<lo then value<=lo;
          elsif unsigned(load_value)>hi then value<=hi;
          else value<=unsigned(load_value); end if;
        elsif en='1' then
          if value<lo or value>hi then value<=first;
          elsif (down='0' and value=hi) or (down='1' and value=lo) then
            if WRAP=1 then value<=first; wrap_event<='1'; end if;
          elsif down='1' then value<=value-1;
          else value<=value+1; end if;
        end if;
      end if;
    end if;
  end process;
end architecture;

ss_counter_skip.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_counter_skip is
  generic (WIDTH:positive range 1 to 64:=8; WRAP:natural range 0 to 1:=1;
    SKIP_COUNT:natural range 0 to 4:=0);
  port (clk,rst,en,load,down:in std_logic;
    minimum,maximum,load_value:in std_logic_vector(WIDTH-1 downto 0);
    skip_0,skip_1,skip_2,skip_3:in std_logic_vector(WIDTH-1 downto 0);
    q:out std_logic_vector(WIDTH-1 downto 0);
    valid,wrapped,blocked:out std_logic);
end entity;
architecture rtl of ss_counter_skip is
  type value_list is array(0 to 3) of unsigned(WIDTH-1 downto 0);
  type search_result is record
    value:unsigned(WIDTH-1 downto 0);
    found,crossed:boolean;
  end record;
  signal exclusions:value_list;
  signal value:unsigned(WIDTH-1 downto 0):=(others=>'0');
  signal wrap_event,blocked_event:std_logic:='0';
  function excluded(v:unsigned; values:value_list) return boolean is
  begin
    for i in 0 to SKIP_COUNT-1 loop if v=values(i) then return true; end if; end loop;
    return false;
  end function;
  function search(first,lo,hi:unsigned; values:value_list; backwards,can_wrap:boolean) return search_result is
    variable result:search_result;
    variable candidate:unsigned(WIDTH-1 downto 0):=first;
  begin
    result.value:=first; result.found:=false; result.crossed:=false;
    -- Four exclusions can block at most four distinct candidates.
    for attempt in 0 to 4 loop
      if not excluded(candidate,values) then result.value:=candidate; result.found:=true; exit; end if;
      if (not backwards and candidate=hi) or (backwards and candidate=lo) then
        if not can_wrap then exit; end if;
        result.crossed:=true;
        candidate:=lo; if backwards then candidate:=hi; end if;
      elsif backwards then candidate:=candidate-1;
      else candidate:=candidate+1; end if;
    end loop;
    return result;
  end function;
begin
  exclusions <= (unsigned(skip_0),unsigned(skip_1),unsigned(skip_2),unsigned(skip_3));
  q <= std_logic_vector(value); wrapped <= wrap_event; blocked <= blocked_event;
  valid <= '1' when unsigned(minimum)<=unsigned(maximum) and value>=unsigned(minimum) and
    value<=unsigned(maximum) and not excluded(value,exclusions) else '0';
  process(clk)
    variable lo,hi,first,candidate:unsigned(WIDTH-1 downto 0);
    variable result:search_result;
    variable crossing,can_search:boolean;
  begin
    if rising_edge(clk) then
      lo:=unsigned(minimum); hi:=unsigned(maximum);
      first:=lo; if down='1' then first:=hi; end if;
      wrap_event<='0';
      if rst='1' then
        value<=first; blocked_event<='1';
        if lo<=hi then
          result:=search(first,lo,hi,exclusions,down='1',true);
          if result.found then value<=result.value; blocked_event<='0'; end if;
        end if;
      elsif load='1' or en='1' then
        blocked_event<='1'; crossing:=false; can_search:=lo<=hi; candidate:=first;
        if lo<=hi then
          if load='1' then
            candidate:=unsigned(load_value);
            if candidate<lo then candidate:=lo; elsif candidate>hi then candidate:=hi; end if;
          elsif value>=lo and value<=hi and not excluded(value,exclusions) then
            if (down='0' and value=hi) or (down='1' and value=lo) then
              can_search:=WRAP=1; crossing:=WRAP=1;
            elsif down='1' then candidate:=value-1;
            else candidate:=value+1; end if;
          end if;
          if can_search then
            result:=search(candidate,lo,hi,exclusions,down='1',WRAP=1);
            if result.found then
              value<=result.value; blocked_event<='0';
              if crossing or result.crossed then wrap_event<='1'; end if;
            end if;
          end if;
        end if;
      end if;
    end if;
  end process;
end architecture;

ss_tick.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_tick is
  generic (DIVISOR:positive range 1 to 2147483647:=50000000);
  port (clk,rst,en:in std_logic; tick:out std_logic);
end entity;
architecture rtl of ss_tick is
  signal count:natural range 0 to DIVISOR-1:=0;
  signal event_tick:std_logic:='0';
begin
  tick <= event_tick;
  process(clk) begin
    if rising_edge(clk) then
      event_tick<='0';
      if rst='1' then count<=0;
      elsif en='1' then
        if count=DIVISOR-1 then count<=0; event_tick<='1';
        else count<=count+1; end if;
      end if;
    end if;
  end process;
end architecture;

ss_clock_divider.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_clock_divider is
  generic (DIVISOR:positive range 2 to 2147483647:=50000000);
  port (clk,rst,en:in std_logic; clk_out,tick:out std_logic);
end entity;
architecture rtl of ss_clock_divider is
  constant LOW_CYCLES:positive:=DIVISOR-DIVISOR/2;
  signal count:natural range 0 to DIVISOR-1:=0;
  signal level,event_tick:std_logic:='0';
begin
  clk_out <= level; tick <= event_tick;
  process(clk) begin
    if rising_edge(clk) then
      event_tick<='0';
      if rst='1' then count<=0; level<='0';
      elsif en='1' then
        if count=LOW_CYCLES-1 then level<='1'; end if;
        if count=DIVISOR-1 then count<=0; level<='0'; event_tick<='1';
        else count<=count+1; end if;
      end if;
    end if;
  end process;
end architecture;

ss_timer.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_timer is
  generic (WIDTH:positive range 1 to 64:=32; RETRIGGER:natural range 0 to 1:=1);
  port (clk,rst,en,start,cancel:in std_logic;
    duration:in std_logic_vector(WIDTH-1 downto 0);
    busy,done,pulse:out std_logic;
    remaining:out std_logic_vector(WIDTH-1 downto 0));
end entity;
architecture rtl of ss_timer is
  signal active,completion:std_logic:='0';
  signal left_cycles:unsigned(WIDTH-1 downto 0):=(others=>'0');
begin
  busy <= active; pulse <= active; done <= completion;
  remaining <= std_logic_vector(left_cycles);
  process(clk) begin
    if rising_edge(clk) then
      completion<='0';
      if rst='1' or cancel='1' then active<='0'; left_cycles<=(others=>'0');
      elsif start='1' and (active='0' or RETRIGGER=1) then
        left_cycles<=unsigned(duration);
        if unsigned(duration)=0 then active<='0'; completion<='1';
        else active<='1'; end if;
      elsif en='1' and active='1' then
        if left_cycles=1 then active<='0'; left_cycles<=(others=>'0'); completion<='1';
        else left_cycles<=left_cycles-1; end if;
      end if;
    end if;
  end process;
end architecture;

ss_pwm.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_pwm is
  generic (WIDTH:positive range 1 to 64:=16; ACTIVE_LOW:natural range 0 to 1:=0);
  port (clk,rst,en,load:in std_logic;
    period,duty:in std_logic_vector(WIDTH-1 downto 0);
    pwm,valid:out std_logic);
end entity;
architecture rtl of ss_pwm is
  signal phase,period_reg,duty_reg:unsigned(WIDTH-1 downto 0):=(others=>'0');
  signal active:std_logic;
begin
  valid <= '1' when period_reg/=0 else '0';
  active <= '1' when rst='0' and en='1' and period_reg/=0 and phase<duty_reg else '0';
  pwm <= active when ACTIVE_LOW=0 else not active;
  process(clk) begin
    if rising_edge(clk) then
      if rst='1' then phase<=(others=>'0'); period_reg<=(others=>'0'); duty_reg<=(others=>'0');
      elsif load='1' or (en='1' and (period_reg=0 or phase=period_reg-1)) then
        phase<=(others=>'0'); period_reg<=unsigned(period);
        if unsigned(duty)>unsigned(period) then duty_reg<=unsigned(period);
        else duty_reg<=unsigned(duty); end if;
      elsif en='1' then phase<=phase+1;
      end if;
    end if;
  end process;
end architecture;
